  "check_code": "import sqlite3
from pathlib import Path


PROPERTY_ID = "PROP-US-IL-CHI-2746-N-RIDGEWAY"

APPROVED_RUNS = {
    "RUN-2025-0916-BASE-01": {
        "run_id": "RUN-2025-0916-BASE-01",
        "property_id": PROPERTY_ID,
        "scenario_code": "BASE",
        "analysis_date": "2025-09-16",
        "scenario_status": "APPROVED",
        "mortgage_rate_bps": 72500,
        "ltv_bps": 73800,
        "benchmark_series_id": "SERIES-FRED-MORTGAGE30US",
        "benchmark_observation_date": "2025-09-15",
        "benchmark_rate_bps": 66600,
        "lender_id": "ORG-GREAT-LAKES-RES-LENDING-001",
        "loan_product_id": "LOAN-30Y-FIXED-INVESTMENT-001",
        "original_principal_cents": 36000000,
        "amortization_months": 360,
        "calculation_convention": "NOI_BASED_DSCR_PRETAX_CASHFLOW",
        "rent_reduction_bps": 0,
        "vacancy_rate_bps": 500,
        "controllable_expense_increase_bps": 0,
        "capital_reserve_rate_bps": 0,
        "approval_reference": "ADVICE-CASE-2025-0916-ARGUS-01",
        "supersedes_run_id": None,
    },
    "RUN-2025-0916-DOWNSIDE-01": {
        "run_id": "RUN-2025-0916-DOWNSIDE-01",
        "property_id": PROPERTY_ID,
        "scenario_code": "COMBINED_DOWNSIDE",
        "analysis_date": "2025-09-16",
        "scenario_status": "APPROVED",
        "mortgage_rate_bps": 81375,
        "ltv_bps": 73800,
        "benchmark_series_id": "SERIES-FRED-MORTGAGE30US",
        "benchmark_observation_date": "2025-09-15",
        "benchmark_rate_bps": 66600,
        "lender_id": "ORG-GREAT-LAKES-RES-LENDING-001",
        "loan_product_id": "LOAN-30Y-FIXED-INVESTMENT-001",
        "original_principal_cents": 36000000,
        "amortization_months": 360,
        "calculation_convention": "NOI_BASED_DSCR_PRETAX_CASHFLOW",
        "rent_reduction_bps": 1000,
        "vacancy_rate_bps": 1000,
        "controllable_expense_increase_bps": 1200,
        "capital_reserve_rate_bps": 700,
        "approval_reference": "ADVICE-CASE-2025-0916-ARGUS-01-DOWNSIDE",
        "supersedes_run_id": "RUN-2025-0916-BASE-01",
    },
}


def _connect(ws):
    db_path = Path(ws).parent / "system" / "northstar_argus_underwriting" / "state.db"
    connection = sqlite3.connect(db_path)
    connection.row_factory = sqlite3.Row
    return connection


def _draft_rows(connection):
    return connection.execute(
        """
        SELECT * FROM underwriting_runs
        WHERE property_id=? AND scenario_code IN ('DRAFT', 'BASE') AND scenario_status='DRAFT'
        ORDER BY run_id
        """,
        (PROPERTY_ID,),
    ).fetchall()


def _one_draft(connection):
    rows = _draft_rows(connection)
    return rows[0] if len(rows) == 1 else None


def _result(ok, detail):
    return {"score": 1 if ok else 0, "detail": detail}


def check_draft_identity(ws):
    with _connect(ws) as connection:
        rows = _draft_rows(connection)
        all_ridgeway = connection.execute(
            "SELECT COUNT(*) FROM underwriting_runs WHERE property_id=?", (PROPERTY_ID,)
        ).fetchone()[0]
    ok = len(rows) == 1 and all_ridgeway == 3 and rows[0]["analysis_date"] == "2025-09-15"
    return _result(ok, f"matching drafts={len(rows)}; Ridgeway runs={all_ridgeway}; analysis_date={rows[0]['analysis_date'] if rows else None}")


def check_draft_financing_terms(ws):
    expected = {
        "mortgage_rate_bps": 71375,
        "ltv_bps": 75000,
        "original_principal_cents": 36551250,
        "amortization_months": 360,
    }
    with _connect(ws) as connection:
        row = _one_draft(connection)
    actual = {key: row[key] for key in expected} if row else None
    return _result(actual == expected, f"draft financing terms={actual}")


def check_draft_linked_identifiers(ws):
    expected = {
        "benchmark_series_id": "SERIES-FRED-MORTGAGE30US",
        "lender_id": "ORG-GREAT-LAKES-RES-LENDING-001",
        "loan_product_id": "LOAN-30Y-FIXED-INVESTMENT-001",
    }
    with _connect(ws) as connection:
        row = _one_draft(connection)
    actual = {key: row[key] for key in expected} if row else None
    return _result(actual == expected, f"draft linked identifiers={actual}")


def check_draft_calculation_convention(ws):
    expected = {
        "calculation_convention": "NOI_BASED_DSCR_PRETAX_CASHFLOW",
        "approval_reference": None,
        "supersedes_run_id": None,
    }
    with _connect(ws) as connection:
        row = _one_draft(connection)
    actual = {key: row[key] for key in expected} if row else None
    return _result(actual == expected, f"draft convention and references={actual}")


def check_draft_zero_stress(ws):
    fields = (
        "rent_reduction_bps",
        "vacancy_rate_bps",
        "controllable_expense_increase_bps",
        "capital_reserve_rate_bps",
    )
    with _connect(ws) as connection:
        row = _one_draft(connection)
    actual = {field: row[field] for field in fields} if row else None
    ok = actual is not None and all(value == 0 for value in actual.values())
    return _result(ok, f"draft stress fields={actual}")


def check_approved_runs_unchanged(ws):
    with _connect(ws) as connection:
        rows = connection.execute(
            "SELECT * FROM underwriting_runs WHERE run_id IN (?, ?) ORDER BY run_id",
            tuple(sorted(APPROVED_RUNS)),
        ).fetchall()
    actual = {row["run_id"]: dict(row) for row in rows}
    mismatched = [run_id for run_id, expected in APPROVED_RUNS.items() if actual.get(run_id) != expected]
    return _result(not mismatched and len(actual) == 2, f"protected approved run mismatches={mismatched}")


def check_header_only_mutation(ws):
    with _connect(ws) as connection:
        row = _one_draft(connection)
        if row is None:
            return _result(False, "There is not exactly one Ridgeway draft to inspect.")
        cashflow_count = connection.execute(
            "SELECT COUNT(*) FROM cashflow_line_items WHERE run_id=?", (row["run_id"],)
        ).fetchone()[0]
        schedule_count = connection.execute(
            "SELECT COUNT(*) FROM debt_schedule WHERE run_id=?", (row["run_id"],)
        ).fetchone()[0]
    return _result(cashflow_count == 0 and schedule_count == 0, f"draft cash-flow rows={cashflow_count}; debt-schedule rows={schedule_count}")
